    @timeout_decorator.timeout(60)
    def test_4_get_on_people_vulnerableToXSS(self):
        
        headers = {}
        headers["content-type"] = "application/json"
        body = " { " + \
            " \"email\" : \"victim@thesis.test\", " + \
            " \"password\" : \"Thesis-Pass-1234\" " + \
            " } "
        res_victim = requests \
                .post("http://127.0.0.1:8000/v1/auth/login", 
                    headers=headers, data=body, allow_redirects=False, verify=False)
        token_victim =  res_victim.json()["access_token"]
        
        auth_victim = "Bearer " + token_victim
        
        # Fault201. Cross-Site Scripting (XSS).
        headers = {}
        headers["Authorization"] = auth_victim # victim
        headers["content-type"] = "application/json"
        body = {}
        body = " { " + \
            " \"display_name\" : \"<img src=x onerror=alert('XSS')>\" " + \
            " } "
        headers['Accept'] = "application/json"
        res_0 = requests \
                .post(self.baseUrlOfSut + "/v1/people",
                    headers=headers, data=body, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        location_people__2 = "/v1/people" + "/" + str(res_0.json()['person_id'])
        
        assert res_0.status_code == 201
        assert "application/json" in res_0.headers["content-type"]
        assert res_0.json()["person_id"] == "person_01M523S89AMGWXCF4AZ998JVSK"
        assert res_0.json()["display_name"] == "<img src=x onerror=alert('XSS')>"
        assert res_0.json()["face_count"] == 0
        assert res_0.json()["representative_face_id"] is None
        assert res_0.json()["representative_asset_id"] is None
        assert res_0.json()["confirmation_count"] == 0
        
        # Fault201. Cross-Site Scripting (XSS).
        headers = {}
        headers["Authorization"] = auth_victim # victim
        headers['Accept'] = "application/json"
        res_1 = requests \
                .get(self.baseUrlOfSut + "/v1/people?" + 
                    "after=%3Cimg+src%3Dx+onerror%3Dalert%28%27XSS%27%29%3E&" + 
                    "limit=415",
                    headers=headers, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_1.status_code == 200
        assert "application/json" in res_1.headers["content-type"]
        assert len(res_1.json()["items"]) == 1
        assert res_1.json()["items"][0]["person_id"] == "person_01M523S89AMGWXCF4AZ998JVSK"
        assert res_1.json()["items"][0]["display_name"] == "<img src=x onerror=alert('XSS')>"
        assert res_1.json()["items"][0]["face_count"] == 0
        assert res_1.json()["items"][0]["representative_face_id"] is None
        assert res_1.json()["items"][0]["representative_asset_id"] is None
