        token_victim =  res_victim.json()["access_token"]
        
        auth_victim = "Bearer " + token_victim
        
        # Fault101. Received A Response From API With A Structure/Data That Is Not Matching Its Schema. Type: validation.response.status.unknown Response status 409 not defined for path '/v1/video/chunks/{chunk_id}/fail'.
        headers = {}
        headers["Authorization"] = auth_victim # victim
        headers["content-type"] = "application/json"
        body = {}
        body = " { " + \
            " \"worker_id\" : \"kYcWIyd7083\", " + \
            " \"error_message\" : \"my7RKxuBrxEs\" " + \
            " } "
        headers['Accept'] = "application/json"
        res_0 = requests \
                .post(self.baseUrlOfSut + "/v1/video/chunks/C/fail",
                    headers=headers, data=body, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_0.status_code == 409
        assert "application/json" in res_0.headers["content-type"]
        assert res_0.json()["detail"] == "Chunk not owned by this worker"


